-- 分区表 + 动态分区 完整示例

-- 1. 建分区表
CREATE TABLE dwd_user_login (
  user_id INT,
  login_time STRING
)
PARTITIONED BY (dt STRING);

-- 2. 开启动态分区（分区值由查询结果决定）
SET hive.exec.dynamic.partition=true;
SET hive.exec.dynamic.partition.mode=nonstrict;   -- 允许所有分区列都是动态的

-- 3. 从 ODS 层动态导入：按 ods 表的 dt 自动建分区
INSERT OVERWRITE TABLE dwd_user_login PARTITION (dt)
SELECT user_id, login_time, dt FROM ods_user_login;

-- 4. 查询：只扫指定分区（分区裁剪）
SELECT * FROM dwd_user_login WHERE dt = '2024-01-05';

